    # if (xlist[2] == '7') and xlist[1] in ('x86', 'x86_64') and \
    #    xlist[0] in ('windows', 'darwin', 'linux'):
    #     path = os.path.join(PLATFORM_PATH, *xlist[:2])
    #     names = [x for x in os.listdir(path) if x.startswith('_pytransform.')]
    #     if names:
