def make_macro_for_customized_bytecodes(bytecodes):
    n = len(bytecodes)
    i = random.randrange(0, n)
    j = random.randrange(0, n)
    k = random.randrange(0, 256)
    bytecodes[i] -= 1
    bytecodes[j] ^= k
    return r'''
#define CUSTOMIZE_BYTECODES(bytecodes) do { \
        bytecodes[%s] ++;                  \
        bytecodes[%s] ^= %s;               \
    } while (0)
''' % (i, j, k)


