       rcode = pytransform.get_license_info()['CODE']
       left_days = pytransform.get_expired_days()
       if left_days == -1:
           print('This license for %s is never expired' % rcode)
       else:
           print('This license for %s will be expired in %d days' % \
                 (rcode, left_days))
   except Exception as e:
       print(e)
       sys.exit(1)

