def excepthook(type, exc, traceback):
    try:
        msg = exc.args[0] % exc.args[1:]
    except Exception:
        msg = str(exc)
    logging.error(msg)
    sys.exit(1)


def _set_volatile_home(path):
    if not os.path.exists(path):
        raise RuntimeError('Home path does not exists')

    import utils
