        return filelist

    patterns = []
    for arg in args:
        if arg[0] == '@':
            f = open(arg[1:], 'r')
            for pattern in f.read().splitlines():
                if not pattern.strip() == '':
                    patterns.append(pattern.strip())
            f.close()
        else:
            patterns.append(arg)

    for pat in patterns:
        for name in glob.glob(os.path.join(path, pat)):
            p = os.path.splitext(name)
            filelist.append((name, p[0][n:]))

    return filelist

