    ZipFile(capsule).extractall(path=output)
    logging.info('Extract capsule to %s OK.', output)

    # Fix bootstrap restrict issue from v5.7.0
    make_license(capsule, os.path.join(output, 'license.lic'),
                 '*FLAGS:A*CODE:PyArmor')

    if mode >= 3:
