    elif mode:
        logging.info('Encrypt mode: %s', mode)
        with open(os.path.join(output, 'pyimcore.py'), 'r') as f:
            lines = f.read()
        with open(os.path.join(output, 'pyimcore.py'), 'w') as f:
            i = lines.rfind('\n\n')
            if i == -1:
                raise RuntimeError('Invalid pyimcore.py')
            f.write(lines[:i])
            if mode == 1:
